  created_by_admin_uuid: Maybe<Scalars['uuid']['output']>;
  created_manually: Scalars['Boolean']['output'];
  distance_meters: Maybe<Scalars['float8']['output']>;
  /** Quando o FROTA foi consultado pela última vez. Distingue "conferido e está vazio" de "nunca conferido" — sem isto, nulo em frota_delivered_at significaria as duas coisas. */
  frota_checked_at: Maybe<Scalars['timestamptz']['output']>;
  /** Data de entrega que o FROTA..conhece JÁ tem para este documento (dataent + horaent1), lida pelo protheus-state-sync. Informativa: o guard de sobrescrita é o AND dataent IS NULL do UPDATE. */
  frota_delivered_at: Maybe<Scalars['timestamptz']['output']>;
  /** Qual conhecimento do FROTA respondeu: numcon|serie. Sem ele, a data na tela não é conferível na base de origem. */
  frota_delivery_ref: Maybe<Scalars['String']['output']>;
  latitude: Maybe<Scalars['float8']['output']>;
  /** true stops the resolver from touching occurred_at. Set by human confirmation and by manual registration — a human decision is never silently overwritten. */
  locked: Scalars['Boolean']['output'];
  longitude: Maybe<Scalars['float8']['output']>;
  /** Set when a candidate EARLIER than a locked occurred_at arrived. The decision is preserved and a human is asked to look again. */
  needs_review: Scalars['Boolean']['output'];
  notes: Maybe<Scalars['String']['output']>;
  /** The winning timestamp: earliest detected_at among live candidates, tie-broken by trigger_source.default_priority. */
  occurred_at: Scalars['timestamptz']['output'];
  /** An object relationship */
  occurrence_type: Trip_Occurrence_Type;
  occurrence_type_code: Scalars['String']['output'];
  /** Timestamp a human already entered by hand in PROTHEUS (DUA010, ocorrência E01/E100). A state flag, NOT evidence — it never competes in the earliest-wins rule. Non-null and not written by us means: do not overwrite, and tell the reviewer. */
  protheus_manual_at: Maybe<Scalars['timestamptz']['output']>;
  protheus_manual_checked_at: Maybe<Scalars['timestamptz']['output']>;
  /** DUA_CODOCO:DUA_SEQOCO da linha encontrada já preenchida. */
  protheus_manual_ref: Maybe<Scalars['String']['output']>;
  /** De qual tabela o estado foi lido. Um valor só hoje (dua_occurrence); destino novo entra como origem nova, e é ela que traz a exibição na tela. */
  protheus_manual_source: Maybe<Scalars['String']['output']>;
  status: Scalars['String']['output'];
  /** An object relationship */
  trigger_source: Trip_Trigger_Source;
  trigger_source_code: Scalars['String']['output'];
  /** An object relationship */
  trip: Trip_Trip;
  /** An object relationship */
  trip_stop: Trip_Trip_Stop;
  trip_stop_uuid: Scalars['uuid']['output'];
  trip_uuid: Scalars['uuid']['output'];
  updated_at: Scalars['timestamptz']['output'];
  uuid: Scalars['uuid']['output'];
  /** An object relationship */
  winner_candidate: Maybe<Trip_Occurrence_Candidate>;
  winner_candidate_uuid: Maybe<Scalars['uuid']['output']>;
