/** Append-only evidence of a trip event, one row per (slot, source, source_ref). Never edited. The winner is chosen by trip.fn_resolve_occurrence. */
export type Trip_Occurrence_Candidate = {
  __typename?: 'trip_occurrence_candidate';
  /** How many consecutive GPS pings supported the geofence transition. Anti-jitter evidence: a single ping is not enough to win. */
  confirmation_points: Maybe<Scalars['smallint']['output']>;
  created_at: Scalars['timestamptz']['output'];
  /** An object relationship */
  created_by_admin: Maybe<Admin>;
  created_by_admin_uuid: Maybe<Scalars['uuid']['output']>;
  /** The timestamp that competes in the earliest-wins rule. For keyboard messages this is MENSAGEM.datagps read as UTC, not dt_recebida (which is local time). */
  detected_at: Scalars['timestamptz']['output'];
  discard_reason: Maybe<Scalars['String']['output']>;
  /** Set when the candidate failed a sanity guard (out of the trip time window, for instance). Discarded candidates never win but are kept for audit. */
  discarded_at: Maybe<Scalars['timestamptz']['output']>;
  /** An object relationship */
  discarded_by_admin: Maybe<Admin>;
  /** Quem descartou à mão, por trip.fn_discard_candidate. NULL quando o descarte veio de um guard de sanidade do processador — ou seja, quando ninguém decidiu isso à mão. */
  discarded_by_admin_uuid: Maybe<Scalars['uuid']['output']>;
  distance_meters: Maybe<Scalars['float8']['output']>;
  ignition_on: Maybe<Scalars['Boolean']['output']>;
  latitude: Maybe<Scalars['float8']['output']>;
  longitude: Maybe<Scalars['float8']['output']>;
  /** An object relationship */
  occurrence_type: Trip_Occurrence_Type;
  occurrence_type_code: Scalars['String']['output'];
  /** The source row, for audit. Lets a wrong decision be explained without re-querying SQL Server. */
  raw: Maybe<Scalars['jsonb']['output']>;
  /** Identity of the evidence, for idempotency. Conventions: delivery:<trip_id>:<document_number> | mensagem:<MENSAGEM.id> | rastro:<DADO_LIDO.id> | manual:<admin_uuid>:<epoch>. */
  source_ref: Scalars['String']['output'];
  speed_kmh: Maybe<Scalars['float8']['output']>;
  /** An object relationship */
  trigger_source: Trip_Trigger_Source;
  trigger_source_code: Scalars['String']['output'];
  /** An object relationship */
  trip: Trip_Trip;
  /** An object relationship */
  trip_stop: Trip_Trip_Stop;
  trip_stop_uuid: Scalars['uuid']['output'];
  trip_uuid: Scalars['uuid']['output'];
  uuid: Scalars['uuid']['output'];
  /** An array relationship */
  won_occurrences: Array<Trip_Occurrence>;
  /** An aggregate relationship */
  won_occurrences_aggregate: Trip_Occurrence_Aggregate;
};


