/** One row per transport document (DT6_DOC) of a trip — i.e. one destination. A trip has 1..N stops; multiple destinations is the base case. */
export type Trip_Trip_Stop = {
  __typename?: 'trip_trip_stop';
  /** An array relationship */
  candidates: Array<Trip_Occurrence_Candidate>;
  /** An aggregate relationship */
  candidates_aggregate: Trip_Occurrence_Candidate_Aggregate;
  client_code: Maybe<Scalars['String']['output']>;
  /** An object relationship */
  client_location: Maybe<Trip_Client_Location>;
  /** The geographic target for this stop. NULL means the client has no usable coordinate yet, so proximity cannot run for it — delivery can still be detected by receipt or keyboard. */
  client_location_uuid: Maybe<Scalars['uuid']['output']>;
  client_name: Maybe<Scalars['String']['output']>;
  client_store: Maybe<Scalars['String']['output']>;
  created_at: Scalars['timestamptz']['output'];
  /** Logradouro de entrega do CT-e (FROTA..conhece.enddest). Nulo quando o documento não casa com exatamente uma linha do conhecimento. */
  delivery_address: Maybe<Scalars['String']['output']>;
  /** Cidade de entrega do CT-e (FROTA..conhece.ciddest) — a mesma que a cerca de cidade usa. NÃO é a cidade do cadastro do cliente. */
  delivery_city: Maybe<Scalars['String']['output']>;
  /** UF de entrega do CT-e (FROTA..conhece.ufdest). */
  delivery_state: Maybe<Scalars['String']['output']>;
  /** DT6_DOC. The chosen occurrence granularity: the physical delivery is of the document, and several invoices may share one document. */
  document_number: Scalars['String']['output'];
  /** DT6_DATEMI + DT6_HOREMI: quando o CT-e foi gerado no Protheus. Tem hora (100% preenchida, medido em agosto), ao contrário de DT6_DATENT. Aparece na linha do tempo como o evento de emissão do documento. */
  issued_at: Maybe<Scalars['timestamptz']['output']>;
  /** An array relationship */
  occurrences: Array<Trip_Occurrence>;
  /** An aggregate relationship */
  occurrences_aggregate: Trip_Occurrence_Aggregate;
  /** An object relationship */
  trip: Trip_Trip;
  trip_uuid: Scalars['uuid']['output'];
  updated_at: Scalars['timestamptz']['output'];
  uuid: Scalars['uuid']['output'];
};


